"""Require actual native reference position and board containment, then parity."""
import json,sys,math
from pathlib import Path
import pcbnew
from hardware.qualification.two_board_aux_current_08.ldo_local.immutable_inputs import check_tree,check_recorded,sha
from hardware.qualification.two_board_aux_current_08.held_cell.process_adapter import run_recorded
H=Path(sys.argv[1]);OUT=Path(sys.argv[2]);m=json.loads((H/'manifest.json').read_text());src=H/m['bundle_name'];check_tree(src,m);b=pcbnew.LoadBoard(str(src/'power_protection.kicad_pcb'));assert b is not None;f=next(f for f in b.GetFootprints() if f.GetReference()=='P_C907');ref=f.Reference();xy=[ref.GetPosition().x/1e6,ref.GetPosition().y/1e6];assert math.dist(xy,m['expected_global_reference_mm'])<1e-6,xy;edges=b.GetBoardEdgesBoundingBox();assert edges.Contains(ref.GetBoundingBox().GetOrigin()) and edges.Contains(ref.GetBoundingBox().GetEnd());inputs=[src/'power_protection.kicad_pcb',*sorted(src.glob('*.kicad_sch'))];p=run_recorded(['kicad-cli','pcb','drc','--schematic-parity','--format','json','--output',str(OUT/'parity.json'),str(src/'power_protection.kicad_pcb')],OUT/'parity-process',180,inputs);check_recorded(p,{str(p):m['files'][str(p.relative_to(src))] for p in inputs});check_tree(src,m);pr=json.loads((OUT/'parity.json').read_text());assert not pr['schematic_parity'] and len(pr['violations'])==4 and all(v['type']=='clearance' for v in pr['violations']);r={'manifest_sha256':sha(H/'manifest.json'),'script_sha256':sha(Path(__file__)),'candidate_board_sha256':sha(src/'power_protection.kicad_pcb'),'reference_global_mm':xy,'reference_bbox_inside_board_bbox':True,'native_parity_issues':0,'parity_sha256':sha(OUT/'parity.json')};(OUT/'review.json').write_text(json.dumps(r,indent=2)+'\n');print(r)
